## 1. Complete Counter Example

```dart
import 'package:flutter/material.dart';

void main() {
  runApp(const CounterApp());
}

class CounterApp extends StatelessWidget {
  const CounterApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      home: Scaffold(
        appBar: AppBar(
          title: const Text('StatefulWidget Demo'),
        ),
        body: const Center(
          child: CounterCard(),
        ),
      ),
    );
  }
}

class CounterCard extends StatefulWidget {
  const CounterCard({super.key});

  @override
  State<CounterCard> createState() => _CounterCardState();
}

class _CounterCardState extends State<CounterCard> {
  int _count = 0;

  void _increment() {
    setState(() {
      _count++;
    });
  }

  void _decrement() {
    setState(() {
      if (_count > 0) {
        _count--;
      }
    });
  }

  void _reset() {
    setState(() {
      _count = 0;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(24),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              '$_count',
              style: Theme.of(context).textTheme.displayMedium,
            ),
            const SizedBox(height: 16),
            Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                IconButton(
                  onPressed: _decrement,
                  icon: const Icon(Icons.remove),
                ),
                IconButton(
                  onPressed: _increment,
                  icon: const Icon(Icons.add),
                ),
                IconButton(
                  onPressed: _reset,
                  icon: const Icon(Icons.refresh),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}
```

The important sequence is:

```text
Tap button
→ _increment()
→ setState()
→ _count changes
→ build()
→ Text receives new value
```

## 2. Stateful Widget with Lifecycle-Owned Resource

```dart
import 'dart:async';

import 'package:flutter/material.dart';

class TimerLabel extends StatefulWidget {
  const TimerLabel({super.key});

  @override
  State<TimerLabel> createState() => _TimerLabelState();
}

class _TimerLabelState extends State<TimerLabel> {
  Timer? _timer;
  int _seconds = 0;

  @override
  void initState() {
    super.initState();

    _timer = Timer.periodic(const Duration(seconds: 1), (_) {
      if (!mounted) {
        return;
      }

      setState(() {
        _seconds++;
      });
    });
  }

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Text('Elapsed: $_seconds s');
  }
}
```

This demonstrates ownership correctly:

```text
State owns Timer
        ↓
initState creates it
        ↓
Timer changes state
        ↓
setState updates UI
        ↓
dispose cancels Timer
```

The resource lifecycle follows the State lifecycle rather than being recreated inside build().

## 3. Parent-Owned State

```dart
import 'package:flutter/material.dart';

class SelectionPage extends StatefulWidget {
  const SelectionPage({super.key});

  @override
  State<SelectionPage> createState() => _SelectionPageState();
}

class _SelectionPageState extends State<SelectionPage> {
  int _selectedIndex = 0;

  void _select(int index) {
    setState(() {
      _selectedIndex = index;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        SelectionButtons(
          selectedIndex: _selectedIndex,
          onSelected: _select,
        ),
        SelectedContent(index: _selectedIndex),
      ],
    );
  }
}

class SelectionButtons extends StatelessWidget {
  const SelectionButtons({
    required this.selectedIndex,
    required this.onSelected,
    super.key,
  });

  final int selectedIndex;
  final ValueChanged<int> onSelected;

  @override
  Widget build(BuildContext context) {
    return Row(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        for (var index = 0; index < 3; index++)
          TextButton(
            onPressed: () => onSelected(index),
            child: Text(
              'Item ${index + 1}',
              style: TextStyle(
                fontWeight: selectedIndex == index
                    ? FontWeight.bold
                    : FontWeight.normal,
              ),
            ),
          ),
      ],
    );
  }
}

class SelectedContent extends StatelessWidget {
  const SelectedContent({required this.index, super.key});

  final int index;

  @override
  Widget build(BuildContext context) {
    return Text('Selected item: ${index + 1}');
  }
}
```

Here the child widgets remain stateless. The parent owns the state because both the selection controls and content depend on the same value.

## 4. Do Not Mutate State Outside setState

Incorrect:

```dart
void _increment() {
  _count++;
}
```

Correct:

```dart
void _increment() {
  setState(() {
    _count++;
  });
}
```

The important point is not that every assignment in a State object must mechanically use setState. The important point is that a mutation that should cause the UI represented by that State to update must notify Flutter through setState().

## 5. Keep build() Declarative

Prefer:

```dart
@override
Widget build(BuildContext context) {
  return Text(
    _isSelected ? 'Selected' : 'Not selected',
  );
}
```

rather than performing imperative UI mutations inside build().

The build method should derive the widget tree from the current state.
